import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";

/** Private file storage. Local disk for development, Supabase Storage in production. */
export interface FileStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

const KEY_PATTERN = /^[a-z0-9-]+(\/[a-z0-9-]+)*\.[a-z0-9]+$/;

// Keys are generated by the server; still refuse anything that could escape the root.
function checkKey(key: string) {
  if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`);
  return key;
}

export function createLocalStorage(root: string): FileStorage {
  const base = resolve(root);
  const pathFor = (key: string) => join(base, checkKey(key));
  return {
    async put(key, data) {
      const path = pathFor(key);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, data, { flag: "wx" });
    },
    async get(key) {
      return readFile(pathFor(key));
    },
    async delete(key) {
      await rm(pathFor(key), { force: true });
    },
  };
}

export interface SupabaseStorageOptions {
  url: string;
  serviceKey: string;
  bucket: string;
  fetchFn?: typeof fetch;
}

/** Talks to the Storage REST API; the bucket must be private. Server-side only (service key). */
export function createSupabaseStorage({
  url,
  serviceKey,
  bucket,
  fetchFn = fetch,
}: SupabaseStorageOptions): FileStorage {
  const root = `${url.replace(/\/+$/, "")}/storage/v1`;
  const headers = {
    Authorization: `Bearer ${serviceKey}`,
    apikey: serviceKey,
  };
  const objectUrl = (key: string, authenticated = false) =>
    `${root}/object/${authenticated ? "authenticated/" : ""}${bucket}/${checkKey(key)}`;

  async function expectOk(response: Response, action: string) {
    if (!response.ok)
      throw new Error(
        `Storage ${action} failed with status ${response.status}`,
      );
  }

  return {
    async put(key, data) {
      const response = await fetchFn(objectUrl(key), {
        method: "POST",
        headers: {
          ...headers,
          "Content-Type": "application/octet-stream",
          "x-upsert": "false",
        },
        body: new Uint8Array(data),
      });
      await expectOk(response, "upload");
    },
    async get(key) {
      const response = await fetchFn(objectUrl(key, true), { headers });
      await expectOk(response, "download");
      return Buffer.from(await response.arrayBuffer());
    },
    async delete(key) {
      const response = await fetchFn(`${root}/object/${bucket}`, {
        method: "DELETE",
        headers: { ...headers, "Content-Type": "application/json" },
        body: JSON.stringify({ prefixes: [checkKey(key)] }),
      });
      await expectOk(response, "delete");
    },
  };
}

export function getStorage(): FileStorage {
  if (process.env.STORAGE_DRIVER === "supabase") {
    const { SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, SUPABASE_BUCKET } =
      process.env;
    if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY)
      throw new Error(
        "STORAGE_DRIVER=supabase needs SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY",
      );
    return createSupabaseStorage({
      url: SUPABASE_URL,
      serviceKey: SUPABASE_SERVICE_ROLE_KEY,
      bucket: SUPABASE_BUCKET ?? "teacher-documents",
    });
  }
  return createLocalStorage(process.env.STORAGE_DIR ?? ".storage");
}
